insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 11, 'Mas os filhos de Coré não morreram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 12, 'Os filhos de Simeão por suas famílias: de Nemuel, a família dos nemuelitas; de Jamim, a família dos jaminitas; de Jaquim, a família dos jaquinitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 13, 'De Zerá, a família dos zeraítas; de Saul, a família dos saulitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 14, 'Estas são as famílias dos simeonitas, vinte e dois mil e duzentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 15, 'Os filhos de Gade por suas famílias: de Zefom, a família dos zefonitas; de Hagi, a família dos hagitas; de Suni, a família dos sunitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 16, 'De Ozni, a família dos oznitas; de Eri, a família dos eritas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 17, 'De Arodi, a família dos aroditas; de Areli, a família dos arelitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 18, 'Estas são as famílias de Gade, por seus contados, quarenta mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 19, 'Os filhos de Judá: Er e Onã; e Er e Onã morreram na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 20, 'E foram os filhos de Judá por suas famílias: de Selá, a família dos selanitas; de Perez, a família dos perezitas; de Zerá, a família dos zeraítas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 21, 'E foram os filhos de Perez: de Hezrom, a família dos hezronitas; de Hamul, a família dos hamulitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 22, 'Estas são as famílias de Judá, por seus contados, setenta e seis mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 23, 'Os filhos de Issacar por suas famílias: de Tola, a família dos tolaítas; de Puá a família dos puvitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 24, 'De Jasube, a família dos jasubitas; de Sinrom, a família dos sinronitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 25, 'Estas são as famílias de Issacar, por seus contados, sessenta e quatro mil e trezentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 26, 'Os filhos de Zebulom por suas famílias: de Serede, a família dos sereditas; de Elom, a família dos elonitas; de Jaleel, a família dos jaleelitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 27, 'Estas são as famílias dos zebulonitas, por seus contados, sessenta mil e quinhentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 28, 'Os filhos de José por suas famílias: Manassés e Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 29, 'Os filhos de Manassés: de Maquir, a família dos maquiritas; e Maquir gerou a Gileade; de Gileade, a família dos gileaditas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 30, 'Estes são os filhos de Gileade: de Jezer, a família dos jezeritas; de Heleque, a família dos helequitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 31, 'De Asriel, a família dos asrielitas: de Siquém, a família dos siquemitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 32, 'De Semida, a família dos semidaítas; de Héfer, a família dos heferitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 33, 'E Zelofeade, filho de Héfer, não teve filhos somente filhas: e os nomes das filhas de Zelofeade foram Maalá, e Noa, e Hogla, e Milca, e Tirza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 34, 'Estas são as famílias de Manassés; e seus contados, cinquenta e dois mil e setecentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 35, 'Estes são os filhos de Efraim por suas famílias: de Sutela, a família dos sutelaítas; de Bequer, a família dos bequeritas; de Taã, a família dos taanitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 36, 'E estes são os filhos de Sutela: de Erã, a família dos eranitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 37, 'Estas são as famílias dos filhos de Efraim, por seus contados, trinta e dois mil e quinhentos. Estes são os filhos de José por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 38, 'Os filhos de Benjamim por suas famílias: de Belá, a família dos belaítas; de Asbel, a família dos asbelitas; de Airã, a família dos airamitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 39, 'De Sufã, a família dos sufamitas; de Hufã, a família dos hufamitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 40, 'E os filhos de Belá foram Arde e Naamã: de Arde, a família dos arditas; de Naamã, a família dos naamanitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 41, 'Estes são os filhos de Benjamim por suas famílias; e seus contados, quarenta e cinco mil e seiscentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 42, 'Estes são os filhos de Dã por suas famílias: de Suã, a família dos suamitas. Estas são as famílias de Dã por suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 43, 'Todas as famílias dos suamitas, por seus contados, sessenta e quatro mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 44, 'Os filhos de Aser por suas famílias: de Imna, a família dos imnaítas; de Isvi, a família dos isvitas; de Berias, a família dos beriitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 45, 'Os filhos de Berias: de Héber, a família dos heberitas; de Malquiel, a família dos malquielitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 46, 'E o nome da filha de Aser foi Sera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 47, 'Estas são as famílias dos filhos de Aser, por seus contados, cinquenta e três mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 48, 'Os filhos de Naftali por suas famílias: de Jazeel, a família dos jazeelitas; de Guni, a família dos gunitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 49, 'De Jezer, a família dos jezeritas; de Silém, a família dos silemitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 50, 'Estas são as famílias de Naftali por suas famílias; e seus contados, quarenta e cinco mil e quatrocentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 51, 'Estes são os contados dos filhos de Israel, seiscentos e um mil setecentos e trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 52, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 53, 'A estes se repartirá a terra em herança, pela conta dos nomes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 54, 'Aos mais darás maior herança, e aos menos menor; e a cada um se lhe dará sua herança conforme seus contados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 55, 'Porém a terra será repartida por sorteio; e pelos nomes das tribos de seus pais herdarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 56, 'Conforme a sorte será repartida sua herança entre o grande e o pequeno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 57, 'E os contados dos levitas por suas famílias são estes: de Gérson, a família dos gersonitas; de Coate, a família dos coatitas; de Merari, a família dos meraritas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 58, 'Estas são as famílias dos levitas: a família dos libnitas, a família dos hebronitas, a família dos malitas, a família dos musitas, a família dos coraítas. E Coate gerou a Anrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 59, 'E a mulher de Anrão se chamou Joquebede, filha de Levi, a qual nasceu a Levi no Egito: esta deu à luz de Anrão a Arão e a Moisés, e a Miriã sua irmã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 60, 'E a Arão nasceram Nadabe e Abiú, Eleazar e Itamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 61, 'Mas Nadabe e Abiú morreram, quando ofereceram fogo estranho diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 62, 'E os contados dos levitas foram vinte e três mil, todos homens de um mês acima: porque não foram contados entre os filhos de Israel, porquanto não lhes havia de ser dada herança entre os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 63, 'Estes são os contados por Moisés e Eleazar o sacerdote, os quais contaram os filhos de Israel nos campos de Moabe, junto ao Jordão de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 64, 'E entre estes ninguém havia dos contados por Moisés e Arão o sacerdote, os quais contaram aos filhos de Israel no deserto de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 26, 65, 'Porque o SENHOR lhes disse: Hão de morrer no deserto: e não restou homem deles, a não ser Calebe filho de Jefoné, e Josué filho de Num.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 1, 'E as filhas de Zelofeade, filho de Héfer, filho de Gileade, filho de Maquir, filho de Manassés, das famílias de Manassés, filho de José, os nomes das quais eram Maalá, e Noa, e Hogla, e Milca, e Tirza, chegaram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 2, 'E apresentaram-se diante de Moisés, e diante do sacerdote Eleazar, e diante dos príncipes, e de toda a congregação, à porta do tabernáculo do testemunho, e disseram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 3, 'Nosso pai morreu no deserto, o qual não esteve na junta que se reuniu contra o SENHOR na companhia de Coré: mas sim que em seu pecado morreu, e não teve filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 4, 'Por que será tirado o nome de nosso pai dentre sua família, por não haver tido filho? Dá-nos herança entre os irmãos de nosso pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 5, 'E Moisés levou sua causa diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 6, 'E o SENHOR respondeu a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 7, 'Bem dizem as filhas de Zelofeade: hás de dar-lhes possessão de herança entre os irmãos de seu pai; e passarás a herança de seu pai a elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 8, 'E aos filhos de Israel falarás, dizendo: Quando alguém morrer sem filhos, passareis sua herança à sua filha:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 9, 'E se não tiver filha, dareis sua herança a seus irmãos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 10, 'E se não tiver irmãos, dareis sua herança aos irmãos de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 11, 'E se seu pai não tiver irmãos, dareis sua herança a seu parente mais próximo de sua linhagem, o qual a possuirá: e será aos filhos de Israel por estatuto de regulamento, como o SENHOR mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 12, 'E o SENHOR disse a Moisés: Sobe a este monte Abarim, e verás a terra que dei aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 13, 'E depois que a houverdes visto, tu também serás recolhido ao teus povo, como foi reunido o teu irmão Arão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 14, 'pois fostes rebeldes no deserto de Zim, no conflito da congregação, ao meu mandado de me santificar nas águas à vista deles. Essas são as águas do conflito de Cades no deserto de Zim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 15, 'Então Moisés respondeu ao SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 16, 'Que o SENHOR, Deus dos espíritos de toda carne, ponha um homem sobre a congregação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 17, 'que saia diante deles, que entre diante deles, que os faça sair e os faça entrar; para que a congregação do SENHOR não seja como ovelhas sem pastor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 18, 'E o SENHOR disse a Moisés: Toma a Josué filho de Num, homem no qual há espírito, e porás tua mão sobre ele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 19, 'E o porás diante de Eleazar o sacerdote, e diante de toda a congregação; e lhe darás ordens em presença deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 20, 'E porás de tua dignidade sobre ele, para que toda a congregação dos filhos de Israel lhe obedeçam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 21, 'E ele estará diante de Eleazar o sacerdote, e a ele perguntará pelo juízo do Urim diante do SENHOR: pelo dito dele sairão, e pelo dito dele entrarão, ele, e todos os filhos de Israel com ele, e toda a congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 22, 'E Moisés fez como o SENHOR lhe havia mandado; que tomou a Josué, e lhe pôs diante de Eleazar o sacerdote, e de toda a congregação:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 27, 23, 'E pôs sobre ele suas mãos, e deu-lhe ordens, como o SENHOR havia mandado por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 2, 'Manda aos filhos de Israel, e dize-lhes: Da minha oferta, do meu pão com os meus holocaustos em aroma agradável para mim, tereis cuidado de as oferecer a mim no tempo devido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 3, 'E lhes dirás: Esta é a oferta queimada que apresentareis ao SENHOR: dois cordeiros sem mácula de ano, cada dia, será o holocausto contínuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 4, 'Um cordeiro oferecerás pela manhã, e o outro cordeiro oferecerás entre as duas tardes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 5, 'E a décima de um efa de boa farinha, amassada com uma quarta parte de um him de azeite prensado, em oferta de cereais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 6, 'É holocausto contínuo, que foi feito no monte Sinai em cheiro suave, oferta queimada ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 7, 'E sua libação, a quarta parte de um him com cada cordeiro: derramarás libação de superior vinho ao SENHOR no santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 8, 'E oferecerás o segundo cordeiro entre as duas tardes: conforme a oferta da manhã, e conforme sua libação oferecerás, oferta queimada em cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 9, 'Mas no dia do sábado dois cordeiros de ano sem defeito, e dois décimos [de efa] de flor de farinha amassada com azeite, por oferta de cereais, com sua libação:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 10, 'É o holocausto do sábado em cada sábado, além do holocausto contínuo e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 11, 'E nos princípios de vossos meses oferecereis em holocausto ao SENHOR dois bezerros das vacas, e um carneiro, e sete cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 12, 'E três décimos [de efa] de boa farinha amassada com azeite, por oferta de cereais com cada bezerro; e dois décimos [de efa] de boa farinha amassada com azeite, por oferta de cereais com cada carneiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 13, 'E um décimo [de efa] de boa farinha amassada com azeite, em oferta de cereais com cada cordeiro; holocausto de aroma suave, oferta queimada ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 14, 'E suas libações de vinho, meio him com cada bezerro, e o terço de um him com cada carneiro, e a quarta parte de um him com cada cordeiro. Este é o holocausto de cada mês por todos os meses do ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 15, 'E um bode macho em expiação se oferecerá ao SENHOR, além do holocausto contínuo com sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 16, 'Mas no mês primeiro, aos catorze do mês será a páscoa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 17, 'E aos quinze dias deste mês, a solenidade: por sete dias se comerão pães ázimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 18, 'No primeiro dia, santa convocação; nenhuma obra servil fareis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 19, 'E oferecereis por oferta queimada em holocausto ao SENHOR dois bezerros das vacas, e um carneiro, e sete cordeiros de um ano; sem defeito os tomareis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 20, 'E sua oferta de cereais de farinha amassada com azeite: três décimos [de efa] com cada bezerro, e dois décimos com cada carneiro oferecereis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 21, 'Com cada um dos sete cordeiros oferecereis um décimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 22, 'e um bode macho por expiação, para vos reconciliar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 23, 'Isto oferecereis além do holocausto da manhã, que é o holocausto contínuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 24, 'Conforme isto oferecereis cada um dos sete dias, alimento e oferta queimada em cheiro suave ao SENHOR; será oferecido além do holocausto contínuo, com sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 25, 'E no sétimo dia tereis santa convocação; nenhuma obra servil fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 26, 'Também no dia das primícias, quando oferecerdes oferta de cereais novos ao SENHOR em vossas semanas, tereis santa convocação; nenhuma obra servil fareis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 27, 'E oferecereis em holocausto, em cheiro suave ao SENHOR, dois bezerros das vacas, um carneiro, sete cordeiros de um ano;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 28, 'E a oferta de cereais deles, boa farinha amassada com azeite, três décimos [de efa] com cada bezerro, dois décimos com cada carneiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 29, 'com cada um dos sete cordeiros uma décimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 30, 'um bode macho, para fazer expiação por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 28, 31, 'Vós os oferecereis, além do holocausto contínuo com suas ofertas de cereais, e suas libações; vós os [apresentareis] sem defeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 1, 'E no sétimo mês, ao primeiro do mês tereis santa convocação: nenhuma obra servil fareis; vos será dia de soar as trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 2, 'E oferecereis holocausto por cheiro suave ao SENHOR, um bezerro das vacas, um carneiro, sete cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 3, 'E a oferta de cereais deles, de boa farinha amassada com azeite, três décimos [de efa] com cada bezerro, dois décimos com cada carneiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 4, 'e com cada um dos sete cordeiros, uma décimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 5, 'E um bode macho por expiação, para reconciliar-vos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 6, 'Além do holocausto do mês, e sua oferta de cereais, e o holocausto contínuo e sua oferta de cereais, e suas libações, conforme sua lei, por oferta queimada ao SENHOR em cheiro suave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 7, 'E no dez deste mês sétimo tereis santa convocação, e afligireis vossas almas: nenhuma obra fareis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 8, 'E oferecereis em holocausto ao SENHOR por cheiro suave, um bezerro das vacas, um carneiro, sete cordeiros de ano; sem defeito os tomareis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 9, 'E suas ofertas de cereais, boa farinha amassada com azeite, três décimos [de efa] com cada bezerro, dois décimos com cada carneiro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 10, 'e com cada um dos sete cordeiros, um décimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 11, 'um bode macho por expiação; além da oferta das expiações pelo pecado, e do holocausto contínuo, e de suas ofertas de cereais, e de suas libações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 12, 'Também aos quinze dias do mês sétimo tereis santa convocação; nenhuma obra servil fareis, e celebrareis solenidade ao SENHOR por sete dias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 13, 'E oferecereis em holocausto, em oferta queimada ao SENHOR em cheiro suave, treze bezerros das vacas, dois carneiros, catorze cordeiros de um ano; devem ser sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 14, 'E as ofertas de cereais deles, de boa farinha amassada com azeite, três décimos [de efa] com cada um dos treze bezerros, dois décimos com cada um dos dois carneiros,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 15, 'e com cada um dos catorze cordeiros, um décimo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 16, 'e um bode macho por expiação; além do holocausto contínuo, sua oferta de cereais e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 17, 'E no segundo dia, doze bezerros das vacas, dois carneiros, catorze cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 18, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 19, 'E um bode macho por expiação: além do holocausto contínuo, e sua oferta de cereais e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 20, 'E no dia terceiro, onze bezerros, dois carneiros, catorze cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 21, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 22, 'E um bode macho por expiação: além do holocausto contínuo, e sua oferta de alimentos e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 23, 'E no quarto dia, dez bezerros, dois carneiros, catorze cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 24, 'Suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 25, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 26, 'E no quinto dia, nove bezerros, dois carneiros, catorze cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 27, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 28, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 29, 'E no sexto dia, oito bezerros, dois carneiros, catorze cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 30, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 31, 'E um bode macho por expiação: além do holocausto contínuo, sua oferta de cereais e suas libações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 32, 'E no sétimo dia, sete bezerros, dois carneiros, catorze cordeiros de ano sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 33, 'E suas ofertas de cereais e suas libações com os bezerros, com os carneiros, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 34, 'E um bode macho por expiação: além do holocausto contínuo, com sua oferta de cereais e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 35, 'No oitavo dia tereis solenidade; nenhuma obra servil fareis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 36, 'E oferecereis em holocausto, em oferta de queima de cheiro suave ao SENHOR, um novilho, um carneiro, sete cordeiros de um ano, sem defeito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 37, 'Suas ofertas de cereais e suas libações com o novilho, com o carneiro, e com os cordeiros, segundo o número deles, conforme a lei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 38, 'E um bode macho por expiação: além do holocausto contínuo, com sua oferta de cereais e sua libação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 39, 'Estas coisas oferecereis ao SENHOR em vossas solenidades, além de vossos votos, e de vossas ofertas livres, para vossos holocaustos, e para vossas ofertas de cereais, e para vossas libações e para vossas ofertas pacíficas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 29, 40, 'E Moisés disse aos filhos de Israel, conforme tudo o que o SENHOR lhe havia mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 1, 'E falou Moisés aos príncipes das tribos dos filhos de Israel, dizendo: Isto é o que o SENHOR mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 2, 'Quando alguém fizer voto ao SENHOR, ou fizer juramento ligando sua alma com obrigação, não violará sua palavra: fará conforme tudo o que saiu de sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 3, 'Mas a mulher, quando fizer voto ao SENHOR, e se ligar com obrigação em casa de seu pai, em sua juventude;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 4, 'Se seu pai ouvir seu voto, e a obrigação com que ligou sua alma, e seu pai calar a isso, todos os votos dela serão firmes, e toda obrigação com que houver ligado sua alma, firme será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 5, 'Mas se seu pai lhe vedar no dia que ouvir todos os seus votos e suas obrigações, com que ela houver ligado sua alma, não serão firmes; e o SENHOR a perdoará, porquanto seu pai lhe vedou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 6, 'Porém se for casada, e fizer votos, ou pronunciar de seus lábios coisa com que obriga sua alma;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 7, 'Se seu marido o ouvir, e quando o ouvir calar a isso, os votos dela serão firmes, e a obrigação com que ligou sua alma, firme será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 8, 'Porém se quando seu marido o ouviu, lhe vedou, então o voto que ela fez, e o que pronunciou de seus lábios com que ligou sua alma, será nulo; e o SENHOR o perdoará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 9, 'Mas todo voto de viúva, ou repudiada, com que ligar sua alma, será firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 10, 'E se houver feito voto em casa de seu marido, e houver ligado sua alma com obrigação de juramento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 11, 'Se seu marido ouviu, e calou a isso, e não lhe vedou; então todos os seus votos serão firmes, e toda obrigação com que houver ligado sua alma, firme será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 12, 'Mas se seu marido os anulou no dia que os ouviu; tudo o que saiu de seus lábios quanto a seus votos, e quanto à obrigação de sua alma, será nulo; seu marido os anulou, e o SENHOR a perdoará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 13, 'Todo voto, ou todo juramento obrigando-se a afligir a alma, seu marido o confirmará, ou seu marido o anulará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 14, 'Porém se seu marido calar a isso de dia em dia, então confirmou todos os seus votos, e todas as obrigações que estão sobre ela: confirmou-as, porquanto calou a isso o dia que o ouviu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 15, 'Mas se as anular depois de havê-las ouvido, então ele levará o pecado dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 30, 16, 'Estas são as ordenanças que o SENHOR mandou a Moisés entre o homem e sua mulher, entre o pai e sua filha, durante sua juventude em casa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 2, 'Faze a vingança dos filhos de Israel sobre os midianitas; depois serás recolhido a teus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 3, 'Então Moisés falou ao povo, dizendo: Armai-vos alguns de vós para a guerra, e irão contra Midiã, e farão a vingança do SENHOR em Midiã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 4, 'Mil de cada tribo de todas as tribos dos filhos de Israel, enviareis à guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 5, 'Assim foram dados dos milhares de Israel, mil cada tribo, doze mil a ponto de guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 6, 'E Moisés os enviou à guerra: mil cada tribo enviou: e Fineias, filho de Eleazar sacerdote, foi à guerra com os santos instrumentos, com as trombetas em sua mão para tocar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 7, 'E lutaram contra Midiã, como o SENHOR o mandou a Moisés, e mataram a todo homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 8, 'Mataram também, entre os mortos deles, aos reis de Midiã: Evi, e Requém, e Zur, e Hur, e Reba, cinco reis de Midiã; a Balaão também, filho de Beor, mataram à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 9, 'E levaram cativas os filhos de Israel as mulheres dos midianitas, e suas crianças e todos suas animais, e todos os seus gados; e arrebataram todos os seus pertences.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 10, 'E abrasaram com fogo todas suas cidades, aldeias e castelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 11, 'E tomaram todo o despojo, e toda a presa, tanto de homens como de animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 12, 'E trouxeram a Moisés, e a Eleazar o sacerdote, e à congregação dos filhos de Israel, os cativos e a presa e os despojos, ao acampamento nas planícies de Moabe, que estão junto ao Jordão de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 13, 'E saíram Moisés e Eleazar o sacerdote, e todos os príncipes da congregação, a recebê-los fora do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 14, 'E irou-se Moisés contra os capitães do exército, contra os comandantes de mil e comandantes de cem que voltavam da guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 15, 'E disse-lhes Moisés: Todas as mulheres preservastes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 16, 'Eis que elas foram aos filhos de Israel, por conselho de Balaão, para causar transgressão contra o SENHOR no negócio de Peor; pelo que houve mortandade na congregação do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 17, 'Matai, pois, agora todos os machos entre as crianças: matai também toda mulher que tenha conhecido homem carnalmente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 18, 'E todas as meninas entre as mulheres, que não tenham conhecido ajuntamento de homem, vos preservareis vivas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 19, 'E vós ficai fora do acampamento sete dias: e todos os que houverem matado pessoa, e qualquer um que houver tocado morto, vos purificareis ao terceiro e ao sétimo dia, vós e vossos cativos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 20, 'Também purificareis toda roupa, e todo artigo de peles, e toda obra de pelos de cabra, e todo vaso de madeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 21, 'E Eleazar o sacerdote disse aos homens de guerra que vinham da guerra: Esta é a ordenança da lei que o SENHOR mandou a Moisés:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 22, 'Certamente o ouro, e a prata, bronze, ferro, estanho, e chumbo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 23, 'Tudo o que resiste ao fogo, por fogo o fareis passar, e será limpo, ainda que nas águas de purificação haverá de purificar-se: mas fareis passar por água tudo o que não aguenta o fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 24, 'Além disso lavareis vossas roupas no sétimo dia, e assim sereis limpos; e depois entrareis no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 25, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 26, 'Toma a contagem da presa que se fez, tanto das pessoas como dos animais, tu e o sacerdote Eleazar, e os chefes dos pais da congregação:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 27, 'E partirás pela metade a presa entre os que lutaram, os que saíram à guerra, e toda a congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 28, 'E separarás para o SENHOR o tributo dos homens de guerra, que saíram à guerra: de quinhentos um, tanto das pessoas como dos bois, dos asnos, e das ovelhas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 29, 'Da metade deles o tomarás; e darás a Eleazar o sacerdote a oferta do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 30, 'E da metade pertencente aos filhos de Israel tomarás um de cinquenta, das pessoas, dos bois, dos asnos, e das ovelhas, de todo animal; e os darás aos levitas, que têm a guarda do tabernáculo do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 31, 'E fizeram Moisés e Eleazar o sacerdote como o SENHOR mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 32, 'E foi a presa, o resto da presa que tomaram os homens de guerra, seiscentas e setenta e cinco mil ovelhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 33, 'E setenta e dois mil bois,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 34, 'E setenta e um mil asnos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 35, 'E quanto às pessoas, de mulheres que não conheciam ajuntamento de homem, ao todo trinta e duas mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 36, 'E a metade, a parte dos que haviam saído à guerra, foi o número de trezentas trinta e sete mil e quinhentas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 37, 'E o tributo para o SENHOR das ovelhas foi seiscentas e setenta e cinco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 38, 'E dos bois, trinta e seis mil: e deles o tributo para o SENHOR, setenta e dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 39, 'E dos asnos, trinta mil e quinhentos: e deles o tributo para o SENHOR, setenta e um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 40, 'E das pessoas, dezesseis mil: e delas o tributo para o SENHOR, trinta e duas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 41, 'E deu Moisés o tributo, por elevada oferta ao SENHOR, a Eleazar o sacerdote, como o SENHOR o mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 42, 'E da metade para os filhos de Israel, que separou Moisés dos homens que haviam ido à guerra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 43, '(A metade para a congregação foi: das ovelhas, trezentas e trinta e sete mil e quinhentas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 44, 'E dos bois, trinta e seis mil;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 45, 'E dos asnos, trinta mil e quinhentos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 46, 'E das pessoas, dezesseis mil:)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 47, 'Da metade, pois, para os filhos de Israel tomou Moisés um de cada cinquenta, tanto das pessoas como dos animais, e deu-os aos levitas, que tinham a guarda do tabernáculo do SENHOR; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 48, 'E chegaram a Moisés os chefes dos milhares daquele exército, os comandantes de mil e comandantes de cem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 49, 'E disseram a Moisés: Teus servos tomaram a soma dos homens de guerra que estão em nosso poder, e nenhum faltou de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 50, 'Pelo qual temos oferecido ao SENHOR oferta, cada um do que achou, objetos de ouro, braceletes, pulseiras, anéis, pendentes, e correntes, para fazer expiação por nossas almas diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 51, 'E Moisés e o sacerdote Eleazar receberam o ouro deles, joias, todas elaboradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 52, 'E todo o ouro da oferta que ofereceram ao SENHOR dos comandantes de mil e comandantes de cem, foi dezesseis mil setecentos e cinquenta siclos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 53, 'Os homens do exército haviam despojado cada um para si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 31, 54, 'Receberam, pois, Moisés e o sacerdote Eleazar, o ouro dos comandantes de mil e comandantes de cem, e trouxeram-no ao tabernáculo do testemunho, por memória dos filhos de Israel diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 1, 'E os filhos de Rúben e os filhos de Gade tinham uma muito grande abundância de gado; os quais vendo a terra de Jazer e de Gileade, pareceu-lhes a terra lugar de gado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 2, 'E vieram os filhos de Gade e os filhos de Rúben, e falaram a Moisés, e a Eleazar o sacerdote, e aos príncipes da congregação, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 3, 'Atarote, e Dibom, e Jazer, e Ninra, e Hesbom, e Eleale, e Sebã, e Nebo, e Beom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 4, 'A terra que o SENHOR feriu diante da congregação de Israel, é terra de gado, e teus servos têm gado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 5, 'Portanto, disseram, se achamos favor em teus olhos, seja dada esta terra a teus servos em herança, e não nos faças passar o Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 6, 'E respondeu Moisés aos filhos de Gade e aos filhos de Rúben: Virão vossos irmãos à guerra, e vós ficareis aqui?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 7, 'E por que desencorajais o ânimo dos filhos de Israel, para que não passem à terra que lhes deu o SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 8, 'Assim fizeram vossos pais, quando os enviei desde Cades-Barneia para que vissem a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 9, 'Que subiram até o vale de Escol, e depois que viram a terra, preocuparam o ânimo dos filhos de Israel, para que não viessem à terra que o SENHOR lhes havia dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 10, 'E o furor do SENHOR se acendeu então, e jurou dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 11, 'Os homens que subiram do Egito de vinte anos acima não verão a terra pela qual jurei a Abraão, Isaque, e Jacó, pois não me seguiram por completo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 12, 'exceto Calebe, filho do quenezeu Jefoné, e Josué filho de Num, que seguiram por completo ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 13, 'E o furor do SENHOR se acendeu em Israel, e os fez andar errantes quarenta anos pelo deserto, até que foi acabada toda aquela geração, que havia feito mal diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 14, 'E eis que vós sucedestes em lugar de vossos pais, descendência de homens pecadores, para acrescentar ainda à ira do SENHOR contra Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 15, 'Se vos deixardes de segui-lo, ele voltará outra vez a deixar-vos no deserto, e destruireis a todo este povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 16, 'Então eles se achegaram a ele e disseram: Edificaremos aqui currais para nosso gado, e cidades para nossas crianças;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 17, 'E nós nos armaremos, e iremos com empenho diante dos filhos de Israel, até que os ponhamos em seu lugar; e nossas crianças ficarão em cidades fortes por causa dos moradores da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 18, 'Não voltaremos a nossas casas até que os filhos de Israel possuam cada um sua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 19, 'Porque não tomaremos herança com eles ao outro lado do Jordão nem adiante, porquanto teremos já nossa herança da outra parte do Jordão ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 20, 'Então lhes respondeu Moisés: Se o fizerdes assim, se vos preparardes para ir diante do SENHOR à guerra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 21, 'E passardes todos vós armados o Jordão diante do SENHOR, até que tenha expulsado a seus inimigos de diante de si,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 22, 'E seja aquela terra subjugada diante do SENHOR; logo voltareis, e sereis livres de culpa para com o SENHOR, e para com Israel; e esta terra será vossa em herança diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 23, 'Mas se assim não o fizerdes, eis que havereis pecado ao SENHOR; e sabei que vos alcançará vosso pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 24, 'Edificai-vos cidades para vossas crianças, e currais para vossas ovelhas, e fazei o que saiu de vossa boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 25, 'E falaram os filhos de Gade e os filhos de Rúben a Moisés, dizendo: Teus servos farão como meu senhor mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 26, 'Nossas crianças, nossas mulheres, nossos gados, e todos nossos animais, estarão aí nas cidades de Gileade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 27, 'E teus servos, armados todos de guerra, passarão diante do SENHOR à guerra, da maneira que meu senhor disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 28, 'Então os encomendou Moisés a Eleazar o sacerdote, e a Josué filho de Num, e aos príncipes dos pais das tribos dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 29, 'E disse-lhes Moisés: Se os filhos de Gade e os filhos de Rúben, passarem convosco o Jordão, todos armados para a guerra diante do SENHOR, logo que aquela terra for subjugada diante de vós, lhes dareis a terra de Gileade como propriedade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 30, 'Mas se não passarem armados convosco, então terão propriedade entre vós na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 31, 'E os filhos de Gade e os filhos de Rúben responderam, dizendo: Faremos o que o SENHOR disse a teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 32, 'Nós passaremos armados diante do SENHOR à terra de Canaã, e a propriedade de nossa herança será desta parte do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 33, 'Assim lhes deu Moisés aos filhos de Gade e aos filhos de Rúben, e à meia tribo de Manassés filho de José, o reino de Seom, rei amorreu, e o reino de Ogue, rei de Basã, a terra com suas cidades e termos, as cidades da terra em redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 34, 'E os filhos de Gade edificaram a Dibom, e a Atarote, e a Aroer,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 35, 'E a Atarote-Sofã, e a Jazer, e a Jogbeá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 36, 'E a Bete-Ninra, e a Bete-Harã: cidades fortificadas, e também currais para ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 37, 'E os filhos de Rúben edificaram a Hesbom, e a Eleale, e a Quiriataim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 38, 'E a Nebo, e a Baal-Meom, (mudados os nomes), e a Sibma: e puseram nomes às cidades que edificaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 39, 'E os filhos de Maquir filho de Manassés foram a Gileade, e tomaram-na, e expulsaram aos amorreus que estavam nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 40, 'E Moisés deu Gileade a Maquir filho de Manassés, o qual habitou nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 41, 'Também Jair filho de Manassés foi e tomou suas aldeias, e pôs-lhes por nome Havote-Jair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 32, 42, 'Também Noba foi e tomou a Quenate e suas aldeias, e chamou-lhe Noba, conforme seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 1, 'Estas são as jornadas dos filhos de Israel, os quais saíram da terra do Egito por seus esquadrões, sob a condução de Moisés e Arão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 2, 'E Moisés escreveu suas saídas conforme suas jornadas por ordem do SENHOR. Estas, pois, são suas jornadas conforme suas partidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 3, 'De Ramessés partiram no mês primeiro, aos quinze dias do mês primeiro: no segundo dia da páscoa saíram os filhos de Israel com mão alta, à vista de todos os egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 4, 'Estavam enterrando os egípcios os que o SENHOR havia matado deles, a todo primogênito; havendo o SENHOR feito também juízos em seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 5, 'Partiram, pois, os filhos de Israel de Ramessés, e assentaram acampamento em Sucote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 6, 'E partindo de Sucote, assentaram em Etã, que está ao extremo do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 7, 'E partindo de Etã, voltaram sobre Pi-Hairote, que está diante de Baal-Zefom, e assentaram diante de Migdol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 8, 'E partindo de Pi-Hairote, passaram por meio do mar ao deserto, e andaram caminho de três dias pelo deserto de Etã, e assentaram em Mara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 9, 'E partindo de Mara, vieram a Elim, de onde havia doze fontes de águas, e setenta palmeiras; e assentaram ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 10, 'E partidos de Elim, assentaram junto ao mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 11, 'E partidos do mar Vermelho, assentaram no deserto de Sim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 12, 'E partidos do deserto de Sim, assentaram em Dofca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 13, 'E partidos de Dofca, assentaram em Alus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 14, 'E partidos de Alus, assentaram em Refidim, onde o povo não teve águas para beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 15, 'E partidos de Refidim, assentaram no deserto de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 16, 'E partidos do deserto de Sinai, assentaram em Quibrote-Taavá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 17, 'E partidos de Quibrote-Taavá, assentaram em Hazerote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 18, 'E partidos de Hazerote, assentaram em Ritmá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 19, 'E partidos de Ritmá, assentaram em Rimom-Perez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 20, 'E partidos de Rimom-Perez, assentaram em Libna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 21, 'E partidos de Libna, assentaram em Rissa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 22, 'E partidos de Rissa, assentaram em Queelata,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 23, 'E partidos de Queelata, assentaram no monte de Séfer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 24, 'E partidos do monte de Séfer, assentaram em Harada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 25, 'E partidos de Harada, assentaram em Maquelote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 26, 'E partidos de Maquelote, assentaram em Taate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 27, 'E partidos de Taate, assentaram em Tera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 28, 'E partidos de Tera, assentaram em Mitca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 29, 'E partidos de Mitca, assentaram em Hasmona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 30, 'E partidos de Hasmona, assentaram em Moserote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 31, 'E partidos de Moserote, assentaram em Bene-Jaacã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 32, 'E partidos de Bene-Jaacã, assentaram em Hor-Gidgade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 33, 'E partidos de Hor-Gidgade, assentaram em Jotbatá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 34, 'E partidos de Jotbatá, assentaram em Abrona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 35, 'E partidos de Abrona, assentaram em Eziom-Geber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 36, 'E partidos de Eziom-Geber, assentaram no deserto de Zim, que é Cades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 37, 'E partidos de Cades, assentaram no monte de Hor, na extremidade da terra de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 38, 'E subiu Arão o sacerdote ao monte de Hor, conforme o dito do SENHOR, e ali morreu aos quarenta anos da saída dos filhos de Israel da terra do Egito, no mês quinto, no primeiro dia do mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 39, 'E era Arão de idade de cento e vinte e três anos, quando morreu no monte de Hor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 40, 'E o cananeu, rei de Arade, que habitava ao sul na terra de Canaã, ouviu como haviam vindo os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 41, 'E partidos do monte de Hor, assentaram em Zalmona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 42, 'E partidos de Zalmona, assentaram em Punom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 43, 'E partidos de Punom, assentaram em Obote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 44, 'E partidos de Obote, assentaram em Ijé-Abarim; no termo de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 45, 'E partidos de Ijé-Abarim, assentaram em Dibom-Gade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 46, 'E partidos de Dibom-Gade, assentaram em Almom-Diblataim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 47, 'E partidos de Almom-Diblataim, assentaram nos montes de Abarim, diante de Nebo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 48, 'E partidos dos montes de Abarim, assentaram nos campos de Moabe, junto ao Jordão de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 49, 'Finalmente assentaram junto ao Jordão, desde Bete-Jesimote até Abel-Sitim, nos campos de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 50, 'E falou o SENHOR a Moisés nos campos de Moabe junto ao Jordão de Jericó, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 51, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes passado o Jordão à terra de Canaã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 52, 'Expulsareis a todos os moradores daquela terra de diante de vós, e destruireis todas suas imagens esculpidas, e todas as suas imagens de fundição, e arruinareis todos os seus altares pagãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 53, 'E expulsareis os moradores da terra, e habitareis nela; porque eu a dei a vós para que a possuais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 54, 'E herdareis a terra por sortes por vossas famílias: aos muitos dareis muito por sua herança, e aos poucos dareis menos por herança sua: onde lhe sair a sorte, ali a terá cada um: pelas tribos de vossos pais herdareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 55, 'E se não expulsardes os moradores daquela terra de diante de vós, sucederá que os que deixardes deles serão por aguilhões em vossos olhos, e por espinhos em vossos lados, e vos afligirão sobre a terra em que vós habitardes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 33, 56, 'Será também, que farei a vós como eu pensei fazer a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 2, 'Manda aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra de Canaã, a saber, a terra que vos há de cair em herança, a terra de Canaã segundo seus termos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 3, 'Tereis o lado do sul desde o deserto de Zim até os termos de Edom; e vos será o termo do sul ao extremo do mar salgado até o oriente:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 4, 'E este termo vos irá rodeando desde o sul até a subida de Acrabim, e passará até Zim; e suas saídas serão do sul a Cades-Barneia; e sairá a Hazar-Adar, e passará até Azmom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 5, 'E rodeará este termo, desde Azmom até o ribeiro do Egito, e seus limites serão ao ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 6, 'E o termo ocidental vos será o grande mar: este termo vos será o termo ocidental.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 7, 'E o termo do norte será este: desde o grande mar vos assinalareis o monte de Hor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 8, 'Do monte de Hor assinalareis à entrada de Hamate, e serão as saídas daquele termo a Zedade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 9, 'E sairá este termo a Zifrom, e serão seus limites em Hazar-Enã: este vos será o termo do norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 10, 'E por termo ao oriente vos assinalareis desde Hazar-Enã até Sefã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 11, 'E baixará este termo desde Sefã a Ribla, ao oriente de Aim: e descerá o termo, e chegará à costa do mar de Quinerete ao oriente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 12, 'Depois descerá este termo ao Jordão, e serão suas saídas ao mar Salgado: esta será vossa terra: por seus termos ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 13, 'E mandou Moisés aos filhos de Israel, dizendo: Esta é a terra que herdareis por sorte, a qual mandou o SENHOR que desse às nove tribos, e à meia tribo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 14, 'Porque a tribo dos filhos de Rúben segundo as casas de seus pais, e a tribo dos filhos de Gade segundo as casas de seus pais, e a meia tribo de Manassés, tomaram sua herança:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 15, 'Duas tribos e meia tomaram sua herança desta parte do Jordão de Jericó ao oriente, ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 16, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 17, 'Estes são os nomes dos homens que vos possuirão a terra: Eleazar o sacerdote, e Josué filho de Num.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 18, 'Tomareis também de cada tribo um príncipe, para dar a possessão da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 19, 'E estes são os nomes dos homens: Da tribo de Judá, Calebe filho de Jefoné.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 20, 'E da tribo dos filhos de Simeão, Samuel filho de Amiúde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 21, 'Da tribo de Benjamim; Elidade filho de Quislom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 22, 'E da tribo dos filhos de Dã, o príncipe Buqui filho de Jogli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 23, 'Dos filhos de José: da tribo dos filhos de Manassés, o príncipe Haniel filho de Éfode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 24, 'E da tribo dos filhos de Efraim, o príncipe Quemuel filho de Siftã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 25, 'E da tribo dos filhos de Zebulom, o príncipe Elizafã filho de Parnaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 26, 'E da tribo dos filhos de Issacar, o príncipe Paltiel filho de Azã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 27, 'E da tribo dos filhos de Aser, o príncipe Aiúde filho de Selomi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 28, 'E da tribo dos filhos de Naftali, o príncipe Pedael filho de Amiúde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 34, 29, 'Estes são aos que mandou o SENHOR que fizessem a partição da herança aos filhos de Israel na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 1, 'E falou o SENHOR a Moisés nos campos de Moabe, junto ao Jordão de Jericó, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 2, 'Manda aos filhos de Israel, que deem aos levitas da possessão de sua herança cidades em que habitem: Também dareis aos levitas campos de essas cidades ao redor delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 3, 'E terão eles as cidades para habitar, e os campos delas serão para seus animais, e para seus gados, e para todos seus animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 4, 'E os campos das cidades que dareis aos levitas, serão mil côvados ao redor, desde o muro da cidade para fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 5, 'Logo medireis fora da cidade à parte do oriente dois mil côvados, e à parte do sul dois mil côvados, e à parte do ocidente dois mil côvados, e à parte do norte dois mil côvados, e a cidade em meio: isto terão pelos campos das cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 6, 'E das cidades que dareis aos levitas, seis cidades serão de refúgio, as quais dareis para que o homicida se acolha ali: e também destas dareis quarenta e duas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 7, 'Todas as cidades que dareis aos levitas serão quarenta e oito cidades; elas com seus campos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 8, 'E as cidades que deres da herança dos filhos de Israel, do que muito tomareis muito, e do que pouco tomareis pouco: cada um dará de suas cidades aos levitas segundo a possessão que herdará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 9, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 10, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes passado o Jordão à terra de Canaã,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 11, 'Assinalareis para vós cidades, tereis cidades de refúgio, para onde fuja o homicida que ferir a algum de morte por acidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 12, 'E vos serão aquelas cidades por refúgio do parente, e não morrerá o homicida até que esteja a juízo diante da congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 13, 'Das cidades, pois, que dareis, tereis seis cidades de refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 14, 'Três cidades dareis desta parte do Jordão, e três cidades dareis na terra de Canaã; as quais serão cidades de refúgio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 15, 'Estas seis cidades serão para refúgio aos filhos de Israel, e ao peregrino, e ao que morar entre eles, para que fuja ali qualquer um que ferir de morte a outro por acidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 16, 'E se com instrumento de ferro o ferir e morrer, homicida é; o homicida morrerá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 17, 'E se com pedra da mão, de que podia morrer, o ferir, e morrer, homicida é; o homicida morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 18, 'E se com instrumento de madeira da mão, de que podia morrer, o ferir, e morrer, homicida é; o homicida morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 19, 'O parente do morto, ele matará ao homicida: quando o encontrar, ele lhe matará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 20, 'E se por ódio o empurrou, ou lançou sobre ele alguma coisa por ciladas, e morre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 21, 'Ou por inimizade o feriu com sua mão, e morreu: o feridor morrerá; é homicida; o parente do morto matará ao homicida, quando o encontrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 22, 'Mas se casualmente o empurrou sem inimizades, ou lançou sobre ele qualquer instrumento sem más intenções,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 23, 'Ou bem, sem vê-lo, fez cair sobre ele alguma pedra, de que possa morrer, e morrer, e ele não era seu inimigo, nem procurava seu mal;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 24, 'Então a congregação julgará entre o feridor e o parente do morto conforme estas leis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 25, 'E a congregação livrará ao homicida da mão do parente do morto, e a congregação o fará voltar à seu cidade de refúgio, à qual se havia acolhido; e morará nela até que morra o sumo sacerdote, o qual foi ungido com o azeite santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 26, 'E se o homicida sair fora do termo de sua cidade de refúgio, à qual se refugiou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 27, 'E o parente do morto lhe achar fora do termo da cidade de sua acolhida, e o parente do morto ao homicida matar, não se lhe culpará por isso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 28, 'Pois em sua cidade de refúgio deverá aquele habitar até que morra o sumo sacerdote: e depois que morrer o sumo sacerdote, o homicida voltará à terra de sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 29, 'E estas coisas vos serão por ordenança de regulamento por vossas gerações, em todas as vossas habitações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 30, 'Qualquer um que ferir a alguém, por dito de testemunhas, morrerá o homicida: mas uma só testemunha não fará fé contra alguma pessoa para que morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 31, 'E não tomareis preço pela vida do homicida; porque está condenado a morte: mas inevitavelmente morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 32, 'Nem tampouco tomareis preço do que fugiu à sua cidade de refúgio, para que volte a viver em sua terra, até que morra o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 33, 'E não contaminareis a terra onde estiverdes: porque este sangue profanará a terra: e a terra não será expiada do sangue que foi derramado nela, a não ser pelo sangue do que a derramou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 35, 34, 'Não contamineis, pois, a terra onde habitais, em meio da qual eu habito; porque eu o SENHOR habito em meio dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 1, 'E chegaram os príncipes dos pais da família de Gileade, filho de Maquir, filho de Manassés, das famílias dos filhos de José; e falaram diante de Moisés, e dos príncipes, cabeças de pais dos filhos de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 2, 'E disseram: o SENHOR mandou a meu senhor que por sorte desse a terra aos filhos de Israel em possessão: também mandou o SENHOR a meu senhor, que dê a possessão de Zelofeade nosso irmão a suas filhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 3, 'As quais, se se casarem com alguns dos filhos das outras tribos dos filhos de Israel, a herança delas será assim tirada da herança de nossos pais, e será acrescentada à herança da tribo a que serão unidas: e será removida da porção de nossa herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 4, 'E quando vier o jubileu dos filhos de Israel, a herança delas será acrescentada à herança da tribo de seus maridos; e assim a herança delas será removida da herança da tribo de nossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 5, 'Então Moisés mandou aos filhos de Israel por dito do SENHOR, dizendo: A tribo dos filhos de José fala corretamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 6, 'Isto é o que mandou o SENHOR acerca das filhas de Zelofeade, dizendo: Casem-se como a elas lhes satisfizer, porém na família da tribo de seu pai se casarão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 7, 'Para que a herança dos filhos de Israel não seja passada de tribo em tribo; porque cada um dos filhos de Israel se achegará à herança da tribo de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 8, 'E qualquer filha que possuir herança das tribos dos filhos de Israel, com algum da família da tribo de seu pai se casará, para que os filhos de Israel possuam cada um a herança de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 9, 'E não ande a herança rodando de uma tribo a outra: mas cada uma das tribos dos filhos de Israel se chegue à sua herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 10, 'Como o SENHOR mandou a Moisés, assim fizeram as filhas de Zelofeade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 11, 'E assim Maalá, e Tirsa, e Hogla, e Milca, e Noa, filhas de Zelofeade, se casaram com filhos de seus tios:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 12, 'Da família dos filhos de Manassés, filho de José, foram mulheres; e a herança delas ficou na tribo da família de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 4, 'Números', 'Nm', 36, 13, 'Estes são os mandamentos e os estatutos que mandou o SENHOR por meio de Moisés aos filhos de Israel nos campos de Moabe, junto ao Jordão de Jericó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 1, 'Estas são as palavras que falou Moisés a todo Israel desta parte do Jordão no deserto, na planície diante do mar Vermelho, entre Parã, e Tofel, e Labã, e Hazerote, e Di-Zaabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 2, 'Onze jornadas há desde Horebe, caminho do monte de Seir, até Cades-Barneia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 3, 'E foi, que aos quarenta anos, no mês décimo primeiro, ao primeiro dia do mês, Moisés falou aos filhos de Israel conforme todas as coisas que o SENHOR lhe havia mandado acerca deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 4, 'Depois que feriu a Seom rei dos amorreus, que habitava em Hesbom, e a Ogue rei de Basã, que habitava em Astarote em Edrei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 5, 'Desta parte do Jordão, em terra de Moabe, resolveu Moisés declarar esta lei, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 6, 'O SENHOR nosso Deus nos falou em Horebe, dizendo: Demais haveis estado neste monte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 7, 'Voltai-vos, parti-vos e ide ao monte dos amorreus, e a todos seus vizinhos, na planície, no monte, e nos vales, e ao sul, e à costa do mar, à terra dos cananeus, e o Líbano, até o grande rio, o rio Eufrates.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 8, 'Olhai, eu dei a terra em vossa presença; entrai e possuí a terra que o SENHOR jurou a vossos pais Abraão, Isaque, e Jacó, que lhes daria a eles e à sua descendência depois deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 9, 'E eu vos falei então, dizendo: Eu não posso vos levar só:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 10, 'O SENHOR vosso Deus vos multiplicou, e eis que sois hoje vós como as estrelas do céu em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 11, 'O SENHOR Deus de vossos pais acrescente sobre vós como sois mil vezes, e vos abençoe, como vos prometeu!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 12, 'Como levarei eu só vossos problemas, vossas cargas, e vossos pleitos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 13, 'Dai-me dentre vós, de vossas tribos, homens sábios e entendidos e experientes, para que eu os ponha por vossos chefes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 14, 'E me respondestes, e dissestes: Bom é fazer o que disseste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 15, 'E tomei os principais de vossas tribos, homens sábios e experientes, e os pus por chefes sobre vós, chefes de milhares, e chefes de centenas, e chefes de cinquenta, e líderes de dez, e governadores a vossas tribos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 16, 'E então mandei a vossos juízes, dizendo: Ouvi entre vossos irmãos, e julgai justamente entre o homem e seu irmão, e o que lhe é estrangeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 17, 'Não tenhais acepção de pessoas no juízo: tanto ao pequeno como ao grande ouvireis: não tereis temor de ninguém, porque o juízo é de Deus: e a causa que vos for difícil, a trareis a mim, e eu a ouvirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 18, 'Eu vos mandei, pois, naquele tempo tudo o que havíeis de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 19, 'Então partimos de Horebe, e andamos por todo aquele grande e temível deserto que vistes, pelo caminho montanhoso dos amorreus, como o SENHOR, nosso Deus, havia nos mandado; e chegamos a Cades-Barneia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 20, 'Então eu vos disse: ‘Chegastes à região montanhosa dos amorreus, a qual o SENHOR, nosso Deus, nos dá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 21, 'Eis que o SENHOR, teu Deus, deu diante de ti esta terra; sobe e tomai posse dela, como o SENHOR, o Deus dos teus pais, te disse; não temas nem te apavores.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 22, 'Então todos vós vos aproximastes de mim, e dissestes: ‘Enviemos homens adiante de nós, que nos reconheçam a terra, e nos tragam de volta relato de qual caminho por onde devemos subir, e das cidades aonde devemos ir.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 23, 'E isso me pareceu bem. Então tomei doze homens de vós, um homem de cada tribo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 24, 'Eles se foram, subiram às montanhas, chegaram ao vale de Escol, e o reconheceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 25, 'E tomaram em suas mãos do fruto daquela terra, e o trouxeram a nós, e nos contaram, e disseram: ‘A terra que o SENHOR, nosso Deus, nos dá, é boa.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 26, 'Porém não quisestes subir, mas fostes rebeldes à ordem do SENHOR, vosso Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 27, 'E murmurastes em vossas tendas, dizendo: ‘É porque o SENHOR nos odeia que ele nos tirou da terra do Egito, para nos entregar nas mãos dos amorreus, para nos destruir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 28, 'Para onde subiremos? Nossos irmãos fizeram derreter o nosso coração, dizendo: Este povo é maior e mais alto que nós, as cidades são grandes e muradas até o céu; e também vimos ali filhos de gigantes.’'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 29, 'Então vos disse: Não temais, nem tenhais medo deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 30, 'O SENHOR vosso Deus, o qual vai diante de vós, ele lutará por vós, conforme todas as coisas que fez por vós no Egito diante vossos olhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 31, 'E no deserto viste que o SENHOR teu Deus te trouxe, como traz o homem a seu filho, por todo o caminho que andastes, até que viestes a este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 32, 'E ainda com isto não crestes no SENHOR vosso Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 33, 'O qual ia diante de vós pelo caminho, para reconhecer-vos o lugar onde havíeis de assentar o acampamento, com fogo de noite para vos mostrar o caminho por onde andásseis, e com nuvem de dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 34, 'E ouviu o SENHOR a voz de vossas palavras, e irou-se, e jurou dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 35, 'Não verá homem algum destes desta má geração, a boa terra que jurei havia de dar a vossos pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 36, 'Exceto Calebe filho de Jefoné: ele a verá, e a ele lhe darei a terra que pisou, e a seus filhos; porque cumpriu em seguir ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 37, 'E também contra mim se irou o SENHOR por vós, dizendo: Tampouco tu entrarás ali:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 38, 'Josué filho de Num, que está diante de ti, ele entrará ali: anima-o; porque ele a fará herdar a Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 39, 'E vossas crianças, das quais dissestes serão por presa, e vossos filhos que não sabem hoje bem nem mal, eles entrarão ali, e a eles a darei, e eles a herdarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 40, 'E vós voltai-vos, e parti-vos ao deserto caminho do mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 41, 'Então respondestes e me dissestes: Pecado temos contra o SENHOR; nós subiremos e lutaremos, conforme tudo o que o SENHOR nosso Deus nos mandou. E vos armastes cada um de suas armas de guerra, e vos preparastes para subir ao monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 42, 'E o SENHOR me disse: Dize-lhes: Não subais, nem luteis, pois não estou entre vós; para que não sejais feridos diante de vossos inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 43, 'E vos falei, e não destes ouvido; antes fostes rebeldes ao dito do SENHOR, e persistindo com altivez, subistes ao monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 44, 'E saíram os amorreus, que habitavam naquele monte, a vosso encontro, e vos perseguiram, como fazem as vespas, e vos derrotaram em Seir, perseguindo-vos até Hormá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 45, 'E voltastes, e chorastes diante do SENHOR; mas o SENHOR não escutou vossa voz, nem vos prestou ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 1, 46, 'E estivestes em Cades por muitos dias, como nos dias que estivestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 1, 'E voltamos, e partimo-nos ao deserto caminho do mar Vermelho, como o SENHOR me havia dito; e rodeamos o monte de Seir por muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 2, 'E o SENHOR me falou, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 3, 'Demais rodeastes este monte; voltai-vos ao norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 4, 'E manda ao povo, dizendo: Passando vós pelo termo de vossos irmãos os filhos de Esaú, que habitam em Seir, eles terão medo de vós; mas vós guardai-vos muito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 5, 'Não vos metais com eles; que não vos darei de sua terra nem ainda a pisadura da planta de um pé; porque eu dei por herança a Esaú o monte de Seir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 6, 'Comprareis deles por dinheiro os alimentos, e comereis; e também comprareis deles a água, e bebereis:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 7, 'Pois o SENHOR teu Deus te abençoou em toda obra de tuas mãos: ele sabe que andas por este grande deserto: estes quarenta anos o SENHOR teu Deus foi contigo; e nenhuma coisa te faltou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 8, 'E passamos por nossos irmãos os filhos de Esaú, que habitavam em Seir, pelo caminho da planície de Elate e de Eziom-Geber. E voltamos, e passamos caminho do deserto de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 9, 'E o SENHOR me disse: Não perturbeis a Moabe, nem te empenhes com eles em guerra, que não te darei possessão de sua terra; porque eu dei a Ar por herança aos filhos de Ló.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 10, '(Os emins habitaram nela antes, povo grande, e numeroso, e alto como gigantes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 11, 'Por gigantes eram eles também contados, como os anaquins; e os moabitas os chamam emins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 12, 'E em Seir habitaram antes os horeus, aos quais os filhos de Esaú expulsaram; e os destruíram de diante de si, e moraram em lugar deles; como fez Israel na terra de sua possessão que lhes deu o SENHOR.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 13, 'Levantai-vos agora, e passai o ribeiro de Zerede. E passamos o ribeiro de Zerede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 14, 'E os dias que andamos de Cades-Barneia até que passamos o ribeiro de Zerede, foram trinta e oito anos; até que se acabou toda a geração dos homens de guerra do meio do acampamento, como o SENHOR lhes havia jurado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 15, 'E também a mão do SENHOR foi sobre eles para destruí-los do meio do campo, até acabá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 16, 'E aconteceu que quando se acabaram de morrer todos os homens de guerra dentre o povo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 17, 'O SENHOR me falou, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 18, 'Tu passarás hoje o termo de Moabe, a Ar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 19, 'E te aproximarás diante dos filhos de Amom: não os perturbeis, nem te metas com eles; porque não te tenho de dar possessão da terra dos filhos de Amom; que aos filhos de Ló a dei por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 20, '(Por terra de gigantes foi também ela tida: habitaram nela gigantes em outro tempo, aos quais os amonitas chamavam zanzumins;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 21, 'Povo grande, e numeroso, e alto, como os anaquins; aos quais o SENHOR destruiu de diante dos amonitas, os quais lhes sucederam, e habitaram em seu lugar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 22, 'Como fez com os filhos de Esaú, que habitavam em Seir, de diante dos quais destruiu aos horeus; e eles lhes sucederam, e habitaram em seu lugar até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 23, 'E aos aveus que habitavam em vilas até Gaza, os caftoreus que saíram de Caftor os destruíram, e habitaram em seu lugar.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 24, 'Levantai-vos, parti, e passai o ribeiro de Arnom: eis que dei em tua mão a Seom rei de Hesbom, amorreu, e a sua terra: começa a tomar possessão, e empenha-te com ele em guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 25, 'Hoje começarei a pôr teu medo e teu espanto sobre os povos debaixo de todo o céu, os quais ouvirão tua fama, e tremerão, e se angustiarão diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 26, 'E enviei mensageiros desde o deserto de Quedemote a Seom rei de Hesbom, com palavras de paz, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 27, 'Passarei por tua terra pelo caminho: pelo caminho irei, sem apartar-me à direita nem à esquerda:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 28, 'A comida me venderás por dinheiro e comerei: a água também me darás por dinheiro, e beberei: somente passarei a pé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 29, 'Como o fizeram comigo os filhos de Esaú que habitavam em Seir, e os moabitas que habitavam em Ar; até que passe o Jordão à terra que nos dá o SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 30, 'Mas Seom rei de Hesbom não quis que passássemos pelo território seu; porque o SENHOR teu Deus havia endurecido seu espírito, e obstinado seu coração para entregá-lo em tua mão, como hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 31, 'E disse-me o SENHOR: Eis que eu comecei a dar diante de ti a Seom e a sua terra; começa a tomar possessão, para que herdes sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 32, 'E saiu-nos Seom ao encontro, ele e todo seu povo, para lutar em Jaza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 33, 'Mas o SENHOR nosso Deus o entregou diante de nós; e ferimos a ele e a seus filhos, e a todo seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 34, 'E tomamos então todas suas cidades, e destruímos todas as cidades, homens, e mulheres, e crianças; não deixamos ninguém:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 35, 'Somente tomamos para nós os animais, e os despojos das cidades que havíamos tomado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 36, 'Desde Aroer, que está junto à beira do ribeiro de Arnom, e a cidade que está no ribeiro, até Gileade, não houve cidade que escapasse de nós: todas as entregou o SENHOR nosso Deus em nosso poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 2, 37, 'Somente à terra dos filhos de Amom não chegaste, nem a tudo o que está à beira do ribeiro de Jaboque nem às cidades do monte, nem a lugar algum que o SENHOR nosso Deus havia proibido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 1, 'E voltamos, e subimos caminho de Basã, e saiu-nos ao encontro Ogue rei de Basã para lutar, ele e todo seu povo, em Edrei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 2, 'E disse-me o SENHOR: Não tenhas medo dele, porque em tua mão entreguei a ele e a todo seu povo, e sua terra: e farás com ele como fizeste com Seom rei amorreu, que habitava em Hesbom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 3, 'E o SENHOR nosso Deus entregou também em nossa mão a Ogue rei de Basã, e a todo seu povo, ao qual ferimos até não restar dele ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 4, 'E tomamos então todas suas cidades; não restou cidade que não lhes tomássemos: sessenta cidades, toda a terra de Argobe, do reino de Ogue em Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 5, 'Todas estas eram cidades fortificadas com alto muro, com portas e barras; sem outras muito muitas cidades sem muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 6, 'E as destruímos, como fizemos a Seom rei de Hesbom, destruindo em toda cidade homens, mulheres, e crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 7, 'E tomamos para nós todos os animais, e os despojos das cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 8, 'Também tomamos naquele tempo da mão de dois reis amorreus que estavam desta parte do Jordão, a terra desde o ribeiro de Arnom até o monte de Hermom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 9, '(Os sidônios chamam a Hermom Siriom; e os amorreus, Senir:)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 10, 'Todas as cidades da planície, e todo Gileade, e todo Basã até Salcá e Edrei, cidades do reino de Ogue em Basã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 11, 'Porque somente Ogue rei de Basã havia restado dos gigantes que restaram. Eis que sua cama, uma cama de ferro, não está em Rabá dos filhos de Amom?; o comprimento dela de nove côvados, e sua largura de quatro côvados, ao côvado de um homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 12, 'E esta terra que herdamos então desde Aroer, que está ao ribeiro de Arnom, e a metade do monte de Gileade com suas cidades, dei aos rubenitas e aos gaditas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 13, 'E o resto de Gileade, e todo Basã, do reino de Ogue, dei o à meia tribo de Manassés; toda a terra de Argobe, todo Basã, que se chamava a terra dos gigantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 14, 'Jair filho de Manassés tomou toda a terra de Argobe até o termo dos gessuritas e dos maacatitas; e chamou-a de seu nome Basã-Havote-Jair, até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 15, 'E a Maquir dei a Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 16, 'E aos rubenitas e gaditas dei de Gileade até o ribeiro de Arnom, o meio do ribeiro por termo; até o ribeiro de Jaboque, termo dos filhos de Amom:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 17, 'Assim como a campina, e o Jordão, e o termo, desde Quinerete até o mar da planície, o mar Salgado, as encostas abaixo do Pisga ao oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 18, 'E vos mandei então, dizendo: O SENHOR vosso Deus vos deu esta terra para que a possuais: passareis armados diante de vossos irmãos os filhos de Israel todos os valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 19, 'Somente vossas mulheres, vossas crianças, e vossos gados, (eu sei que tendes muito gado,) ficarão em vossas cidades que vos dei,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 20, 'Até que o SENHOR dê repouso a vossos irmãos, assim como a vós, e herdem também eles a terra que o SENHOR vosso Deus lhes dá à outra parte do Jordão: então vos voltareis cada um a sua herança que eu vos dei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 21, 'Mandei também a Josué então, dizendo: Teus olhos viram tudo o que o SENHOR vosso Deus fez àqueles dois reis: assim fará o SENHOR a todos os reinos aos quais passarás tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 22, 'Não os temais; que o SENHOR vosso Deus, ele é o que luta por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 23, 'E orei ao SENHOR naquele tempo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 5, 'Deuteronômio', 'Dt', 3, 24, 'Senhor DEUS, tu começaste a mostrar a teu servo tua grandeza, e tua mão forte: porque que deus há no céu nem na terra que faça segundo tuas obras, e segundo tuas valentias?')
